"""Regression values generated by calling the original C# assembly."""
import json
from pathlib import Path
import unittest
from unittest.mock import patch
import numpy as np
from histra.elements.interface import Interface
from histra.types.point import Point
from histra.preprocessing import csharp_fibre_geometry as fg

class TestOriginalCSharpInterfaceCells(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.cases = json.loads((Path(__file__).parent/'fixtures/csharp_interface_cells_2026_1_1.json').read_text())['cases']

    def interface(self, case):
        g = case['geometry']
        return Interface(key=case['interface_key'], nrow=g['nrow'], ncol=g['ncol'],
                         vint2d=[Point(x=p[0], y=p[1]) for p in g['vint2d']],
                         reference_e1=tuple(g['e1']), reference_e2=tuple(g['e2']), reference_e3=tuple(g['e3']),
                         reference_origin=Point(*g['origin']))

    def test_scalar_cells_equal_original_csharp_every_coordinate(self):
        for case in self.cases:
            with self.subTest(interface=case['interface_key']):
                i = self.interface(case)
                actual = np.array([fg._csharp_cell_vertices(i, k) for k in range(i.nrow*i.ncol)])
                np.testing.assert_array_equal(actual, np.asarray(case['cells'], dtype=np.float32))

    def test_compiled_cells_equal_original_csharp_every_coordinate(self):
        for case in self.cases:
            with self.subTest(interface=case['interface_key']):
                actual = fg._csharp_interface_cells(self.interface(case))
                np.testing.assert_array_equal(actual, np.asarray(case['cells'], dtype=np.float32))

    def test_fallback_keeps_original_csharp_precision(self):
        with patch.object(fg, 'njit', None):
            for case in self.cases:
                with self.subTest(interface=case['interface_key']):
                    np.testing.assert_array_equal(fg._csharp_interface_cells(self.interface(case)), np.asarray(case['cells'], dtype=np.float32))

if __name__ == '__main__':
    unittest.main()
